"use client";

import { Mail, Phone, Calendar, Download, BadgeCheck, XCircle } from "lucide-react";
import { Card, CardContent } from "@/app/components/ui/card";
import { Table, TableHeader, TableRow, TableHead, TableBody, TableCell } from "@/app/components/ui/table";
import { Badge } from "@/app/components/ui/badge";
import { customers } from "@/app/data/customers";
import Image from "next/image";

export default function CustomersPage() {
  return (
    <div className="flex-1 max-w-7xl mx-auto w-full p-10">
      
      {/* PAGE HEADER */}
      <div className="flex items-center justify-between mb-8">
        <h1 className="text-3xl font-bold text-slate-800">Customers</h1>

        <button className="bg-[#ebe9f1] text-[#5c4da5] px-5 py-3 rounded-xl flex items-center gap-2 hover:bg-[#e2dcf0] transition-colors font-medium shadow-sm">
          <Download size={20} />
          Export
        </button>
      </div>

      {/* OVERVIEW CARDS */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-8">
        <Card className="border-slate-200 shadow-sm bg-white rounded-xl">
          <CardContent className="p-6">
            <p className="text-sm font-medium text-slate-500 mb-2">Total Customers</p>
            <h2 className="text-3xl font-bold text-slate-800">{customers.length}</h2>
          </CardContent>
        </Card>

        <Card className="border-slate-200 shadow-sm bg-white rounded-xl">
          <CardContent className="p-6">
            <p className="text-sm font-medium text-slate-500 mb-2">Active Plans</p>
            <h2 className="text-3xl font-bold text-slate-800">
              {customers.filter(c => c.isActivated).length}
            </h2>
          </CardContent>
        </Card>

        <Card className="border-slate-200 shadow-sm bg-white rounded-xl">
          <CardContent className="p-6">
            <p className="text-sm font-medium text-slate-500 mb-2">Pending Activation</p>
            <h2 className="text-3xl font-bold text-slate-800">
              {customers.filter(c => !c.isActivated).length}
            </h2>
          </CardContent>
        </Card>
      </div>

      {/* TABLE */}
      <Card className="border-slate-200 shadow-sm bg-white rounded-2xl overflow-hidden">
        <CardContent className="p-0">
          <div className="overflow-x-auto">
            <Table>
              <TableHeader className="bg-slate-50">
                <TableRow>
                  <TableHead>Company</TableHead>
                  <TableHead>Customer</TableHead>
                  <TableHead>Plan</TableHead>
                  <TableHead>Period</TableHead>
                  <TableHead>Email</TableHead>
                  <TableHead>Status</TableHead>
                  <TableHead>Invoice</TableHead>
                  <TableHead>Credentials</TableHead>
                </TableRow>
              </TableHeader>

              <TableBody>
                {customers.map((c) => (
                  <TableRow key={c.id} className="hover:bg-slate-50 transition-colors">

                    {/* Company */}
                    <TableCell>
                      <div className="flex items-center gap-3">
                        <Image
                          src={c.companyLogo}
                          width={36}
                          height={36}
                          alt={c.companyName}
                          className="rounded-full"
                        />
                        <div>
                          <p className="font-semibold text-slate-800">{c.companyName}</p>
                          <p className="text-xs text-slate-500 font-mono">{c.id}</p>
                        </div>
                      </div>
                    </TableCell>

                    {/* Customer Name */}
                    <TableCell>
                      <p className="font-semibold">{c.customerName}</p>
                      <p className="text-sm text-slate-500">{c.customerRole}</p>
                    </TableCell>

                    {/* Plan */}
                    <TableCell>
                      <Badge className="bg-purple-100 text-purple-700 font-semibold">
                        {c.plan}
                      </Badge>
                    </TableCell>

                    {/* Dates */}
                    <TableCell>
                      <div className="text-sm text-slate-700">
                        Start: {c.planStart} <br />
                        End: {c.planEnd}
                      </div>
                    </TableCell>

                    {/* Email */}
                    <TableCell>
                      <div className="flex items-center gap-2 text-sm text-slate-700">
                        <Mail size={14} className="text-slate-400" />
                        {c.email}
                      </div>
                    </TableCell>

                    {/* Activated? */}
                    <TableCell>
                      {c.isActivated ? (
                        <div className="flex items-center gap-1.5 text-emerald-600 bg-emerald-50 px-3 py-1 rounded-md w-max border border-emerald-100 text-xs font-semibold">
                          <BadgeCheck size={14} /> Active
                        </div>
                      ) : (
                        <div className="flex items-center gap-1.5 text-rose-600 bg-rose-50 px-3 py-1 rounded-md w-max border border-rose-100 text-xs font-semibold">
                          <XCircle size={14} /> Inactive
                        </div>
                      )}
                    </TableCell>

                    {/* Invoice */}
                    <TableCell>
                      <a
                        href={c.invoice}
                        download
                        className="text-blue-600 hover:underline text-sm"
                      >
                        Download
                      </a>
                    </TableCell>

                    {/* Credentials */}
                    <TableCell>
                      <details className="text-sm">
                        <summary className="cursor-pointer text-slate-700">View</summary>

                        <div className="mt-2 space-y-1 bg-slate-100 p-2 rounded-md">
                          <p className="font-semibold">VPS</p>
                          <p>IP: {c.vpsCredentials.ip}</p>
                          <p>User: {c.vpsCredentials.username}</p>

                          <p className="font-semibold mt-2">Admin</p>
                          <p>Email: {c.adminCredentials.email}</p>
                        </div>
                      </details>
                    </TableCell>

                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}